import {courses,units,findCourse,findUnit,availableUnit,courseHash,unitHash,parseRoute,routeHash} from './catalogue.mjs';
import {loadPreferences,loadUnitProgress,saveUnitProgress,savePreferences,forgetProgress} from './progress.mjs';
import {newPlayState,updatePlay} from './play-engine.mjs';
import {renderPlay} from './play.mjs';
import {alienPieces} from './data/play-unit1.mjs';
import {unit,phrases,numbers,alphabet,lessons,dialogue,questions,mission,topics,tenerRows,estarRows,readingTexts,sessionRoute,communicationTasks,listenings} from './data/unit1.mjs';
import {check,labSentence,labForm,teachingMarkup} from './engine.mjs';
import {newExploreState,renderExplore,updateExplore,questionScene} from './explore.mjs';
import {newUnit2State,updateUnit2State,renderUnit2Overview,renderUnit2Learn,unit2Objects,unit2Expressions} from './unit2-learn.mjs';
import {newWeekState,updateWeekState,renderUnit2Week} from './unit2-week.mjs';
import {newJourneyState,updateJourneyState,renderUnit2Journey,renderUnit2LearnSwitch,renderJourneyOverviewCard} from './unit2-journey.mjs';
const journeyState=newJourneyState();
const weekState=newWeekState();
let route=parseRoute(location.hash);
const state={play:newPlayState(),unit2:newUnit2State(),mode:'en',section:'home',completed:new Set(),saving:false,storageError:false,large:false,lessonOpen:'greetings',vocabTab:'phrases',vocabSearch:'',labKind:'age',labPerson:'yo',labValue:'trece',predAnswer:'',predChecked:false,explore:newExploreState(),q:0,practiceTopic:'all',learnChecks:new Set(),learnExtras:new Set(),readingChecks:new Set(),qValues:{},qFeedback:{},qPractised:new Set(),qAttempted:new Set(),audioNotice:false,listeningAnswers:{},listeningChecked:new Set(),listeningTranscripts:new Set(),audioPositions:{},missionAt:0,missionValues:{},missionFeedback:{},missionDone:new Set(),meetingChoice:'',meetingChecked:false,draft:'',checks:{},reflection:'',helpReturn:null};
try{const p=loadUnitProgress(localStorage,'1st-year','1');if(p)Object.assign(state,p,{section:'home',completed:new Set(p.completed),saving:true});const preferences=loadPreferences(localStorage);if(preferences)Object.assign(state,preferences,{saving:true});}catch{state.storageError=true;}
const $=s=>document.querySelector(s), main=$('#main');
const E=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const T=(en,es)=>state.mode==='es'?es:state.mode==='bi'?`${en} / ${es}`:en;
const L=(en,es)=>state.mode==='bi'?`<span lang="en">${en}</span><span lang="es" class="secondary">${es}</span>`:`<span lang="${state.mode==='es'?'es':'en'}">${state.mode==='es'?es:en}</span>`;
const pair=p=>L(...p);
const teach=p=>L(...p.map(teachingMarkup));
const steps=[['learn','Learn','Aprende','Notice useful language.','Descubre expresiones útiles.'],['explore','Explore','Experimenta','Change it. See what happens.','Cambia algo y observa.'],['practise','Practise','Practica','Try it with helpful feedback.','Practica con feedback útil.'],['communicate','Communicate','Comunica','Use Spanish for a purpose.','Usa el español con un propósito.']];
const go=(id,label,cls='')=>`<a href="#${['home'].includes(id)||id.startsWith('course/')?id:unitHash(id)}" class="${cls}" ${cls==='current'?'aria-current="page"':''}>${label}</a>`;
const button=(action,label,cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${label}</button>`;
function save(){if(!state.saving)return;try{if(route.kind==='unit'&&route.unit==='1')saveUnitProgress(localStorage,route.course,route.unit,{...state,section:state.section==='unit'?'home':state.section},route.level);savePreferences(localStorage,state.mode);state.storageError=false;}catch{state.saving=false;state.storageError=true;}}
function announce(en,es){$('#announcement').textContent=T(en,es);}
// Use the existing persistent live region after rendering; keep focus on the control.
function announceQuestionExperiment(){const scene=questionScene(state.explore);announce(`${scene.question} ${scene.answer} ${scene.title[0]} ${scene.observation[0]} ${scene.experiment[0]} ${scene.nextStep[0]} ${scene.punctuation[0]}`,`${scene.question} ${scene.answer} ${scene.title[0]} ${scene.observation[0]} ${scene.experiment[0]} ${scene.nextStep[0]} ${scene.punctuation[1]}`);}
function complete(step){state.completed.add(step);save();}
function shell(title,content,{step=true}={}){return `<div class="page"><div class="breadcrumb">${go('home',T('Courses','Cursos'))} <span aria-hidden="true"> / </span> ${go(courseHash('1st-year'),'1st Year')} <span aria-hidden="true"> / </span> ${go('unit',unit.title)}</div>${step?stepNav():''}<div class="section-title"><p class="eyebrow">1st Year · Unit 1</p><h1>${title}</h1></div>${content}</div>`;}
function stepNav(){return `<nav class="step-nav" aria-label="${E(T('Unit sections','Apartados de la unidad'))}">${steps.map(([id,en,es],i)=>`<a href="#${unitHash(id)}" ${state.section===id?'aria-current="page"':''}>${i+1}. ${pair([en,es])}${state.completed.has(id)?' <span aria-label="'+E(T('Practice completed','Práctica realizada'))+'">✓</span>':''}</a>`).join('')}<a href="#${unitHash('play')}" ${state.section==='play'?'aria-current="page"':''}>5. ${pair(['Play','Juega'])} · ${T('optional','opcional')}</a></nav>`;}
function stageCards(){return `<div class="grid-four">${steps.map(([id,en,es,desc,desces],i)=>go(id,`<span class="number">0${i+1}</span><h3>${L(en,es)}</h3><p>${L(desc,desces)}</p>${state.completed.has(id)?`<span class="done">✓ ${T('Practice completed','Práctica realizada')}</span>`:''}`,'stage-card')).join('')}</div>`;}
function catalogueBreadcrumb(course,level){return `<nav class="breadcrumb" aria-label="${T('Breadcrumb','Ruta de navegación')}">${go('home',pair(['Courses','Cursos']))}${course?` <span aria-hidden="true"> / </span> ${go(courseHash(course),pair(findCourse(course).title))}`:''}${level?` <span aria-hidden="true"> / </span> ${level.toUpperCase()}`:''}</nav>`;}
function home(){return `<div class="page"><section class="catalogue-intro"><p class="eyebrow">Unas Tapitas de Español</p><h1>${L('A little Spanish.<br>A world of possibilities.','Un poco de español.<br>Un mundo de posibilidades.')}</h1><p class="lead">${L('Choose your course. Learn, explore, practise, communicate and play at your own pace.','Elige tu curso. Aprende, experimenta, practica, comunica y juega a tu ritmo.')}</p><p class="small">${L('English support is always here. Change language whenever you like.','El apoyo en inglés siempre está disponible. Cambia de idioma cuando quieras.')}</p></section><section aria-labelledby="courses-title"><h2 id="courses-title">${pair(['Your Spanish journey','Tu recorrido en español'])}</h2><div class="catalogue-grid">${courses.map((c,i)=>`<article class="panel course-card"><span class="number" aria-hidden="true">0${i+1}</span><h3>${pair(c.title)}</h3><p>${pair(c.description)}</p><p class="tag">${c.id==='1st-year'?pair(['Unit 1 available','Unidad 1 disponible']):c.id==='lc'?pair(['HL & OL · Coming soon','HL y OL · Próximamente']):pair(['Coming soon','Próximamente'])}</p>${go(courseHash(c.id),pair(c.id==='lc'?['View levels','Ver niveles']:['View course','Ver curso']),'primary ghost')}</article>`).join('')}</div></section><section class="note-strip"><div><h2>${pair(['Start with a hello','Empieza con un hola'])}</h2><p>${pair(['1st Year · Unit 1: Hola y bienvenidos is ready. All five sections are open.','1st Year · Unidad 1: Hola y bienvenidos está lista. Sus cinco secciones están disponibles.'])}</p></div>${go('unit',pair(['Open Unit 1','Abrir la Unidad 1']),'primary')}</section></div>`;}
function courseHome(){const c=findCourse(route.course),level=c.levels?.find(l=>l.id===route.level);const listed=units.filter(u=>u.course===c.id&&u.level===route.level);return `<div class="page">${catalogueBreadcrumb(c.id,route.level)}<div class="section-title"><p class="eyebrow">${pair(['Your course','Tu curso'])}</p><h1>${pair(level?.title??c.title)}</h1><p class="lead">${pair(c.description)}</p></div>${c.levels&&!level?`<div class="catalogue-grid">${c.levels.map(l=>`<article class="panel course-card"><h2>${pair(l.title)}</h2><p>${pair(['A connected progression across 5th and 6th Year. Content coming soon.','Una progresión conectada entre 5th y 6th Year. Contenidos próximamente.'])}</p>${go(courseHash(c.id,l.id),pair(['View pathway','Ver itinerario']),'primary ghost')}</article>`).join('')}</div>`:`<h2>${pair(['Units','Unidades'])}</h2><div class="catalogue-grid">${listed.map(u=>`<article class="panel unit-card ${availableUnit(u)?'':'in-development'}"><p class="eyebrow">${T('Unit','Unidad')} ${u.id}</p><h3 lang="es">${u.title}</h3><p>${pair(u.description)}</p><p class="tag">${u.status==='partial'?pair(['Learn · Block A available · Block B available · Block C available','Learn · Bloque A disponible · Bloque B disponible · Bloque C disponible']):availableUnit(u)?pair(['Complete · Available','Completa · Disponible']):pair(['In development','En desarrollo'])}</p>${availableUnit(u)?go(unitHash('overview',c.id,u.id,route.level),pair(['Open unit','Abrir unidad']),'primary'): `<p class="small">${pair(['Activities are not available yet.','Las actividades todavía no están disponibles.'])}</p>`}</article>`).join('')}<article class="panel in-development"><h3>${pair(['More units to come','Próximas unidades'])}</h3><p>${pair(['New units will appear here when they are ready.','Las nuevas unidades aparecerán aquí cuando estén listas.'])}</p></article></div>`}</div>`;}

function unitHome(){const next=steps.find(([id])=>!state.completed.has(id))?.[0]??'communicate';return `<div class="page">${catalogueBreadcrumb('1st-year')}${stepNav()}<section class="hero"><div><p class="eyebrow">1st Year · ${T('Your first unit','Tu primera unidad')}</p><h1>${L('Your Spanish starts<br>with a hello.','Tu español empieza<br>con un hola.')}</h1><p class="lead">${L('Learn at your own pace. Discover in your own way.','Aprende a tu ritmo. Descubre a tu manera.')}</p><div class="hero-actions">${go(next,pair([state.completed.size?'Continue my unit':'Start with a hello',state.completed.size?'Continuar mi unidad':'Empieza con un hola']),'primary')}${go('vocabulary',pair(['Useful expressions','Expresiones útiles']),'primary ghost')}</div><p class="small">${L('English support is always here. Change language whenever you like.','El apoyo en inglés siempre está disponible. Cambia de idioma cuando quieras.')}</p></div><div class="meeting-art" aria-label="${E(T('Fictional meeting cards','Tarjetas de encuentro ficticias'))}"><p class="eyebrow">${T('A small encounter','Un pequeño encuentro')}</p><div class="identity"><em lang="es">¡Hola!</em><strong>Alba</strong><span lang="es">Tengo trece años.</span></div><div class="identity secondary-card"><strong>Inés</strong><span lang="es">¿Cómo te llamas?</span></div><svg viewBox="0 0 360 42" class="wave" aria-hidden="true"><path d="M0 23Q45 0 90 23T180 23T270 23T360 23" fill="none" stroke="#176a70" stroke-width="2"/></svg></div></section><div class="course-line"><div><p class="eyebrow">${T('Your course','Tu curso')}</p><h2>01 · Hola y bienvenidos</h2></div><span class="tag">${T('A1 foundations · original content','Bases A1 · contenido original')}</span></div><p class="unit-scope">${L(`${lessons.length} learning blocks · ${questions.length} practice activities · ${readingTexts.length} reading texts · ${communicationTasks.length+1} communication tasks`,`${lessons.length} bloques de aprendizaje · ${questions.length} actividades de práctica · ${readingTexts.length} textos de lectura · ${communicationTasks.length+1} tareas comunicativas`)}</p><p class="lead">${L('Meet someone new. Ask their name and age, check a detail, and help the right person find their meeting.','Conoce a alguien. Pregunta su nombre y edad, comprueba un dato y ayuda a la persona correcta a encontrar su encuentro.')}</p>${stageCards()}<section class="note-strip"><div><h3>${L('Play · Three worlds to explore','Play · Tres mundos por descubrir')}</h3><p>${L('A letter workshop, an alien encounter and a secret capsule. Optional, always open.','Un taller de letras, un encuentro extraterrestre y una cápsula secreta. Opcional y siempre abierto.')}</p></div>${go('play',pair(['Choose a game','Elegir un juego']),'primary')}</section><section class="note-strip"><div><h3>${L('Listen to two new encounters','Escucha dos encuentros nuevos')}</h3><p>${L('Two voices, a slow pace and details to discover.','Dos voces, ritmo pausado y datos por descubrir.')}</p></div>${go('listening',pair(['Try the listenings','Prueba los listenings']),'primary')}</section><section class="note-strip"><div><h3>${L('One task. Many ways to get there.','Una tarea con distintos caminos.')}</h3><p>${L('Explore first, revisit a pattern, or go straight to the meeting. Asking for help is part of communicating.','Experimenta, repasa una estructura o ve directamente al encuentro. Pedir ayuda forma parte de la comunicación.')}</p></div>${go('communicate',pair(['See the task','Ver la tarea']),'primary')}</section><div class="two-col"><div class="panel"><h3>${L('Your practice, at your pace','Tu práctica a tu ritmo')}</h3><p>${state.completed.size?L(`${state.completed.size} of 4 sections marked as practised. This is a practice record, not a grade.`,`${state.completed.size} de 4 apartados marcados como practicados. Es un registro de práctica, no una nota.`):L('No sections marked yet. You can visit any section, and nothing is locked.','Todavía no has marcado ningún apartado. Puedes visitar cualquiera; nada está bloqueado.')}</p>${button('options',pair(['Reading and saving options','Opciones de lectura y guardado']),'ghost')}</div><div class="panel"><h3>${L('A platform that can grow with you','Una plataforma que puede crecer contigo')}</h3><p>${L('This review version contains Unit 1 of 1st Year. Future units and courses will use the same shared patterns, with new contexts and greater independence.','Esta versión de revisión contiene la Unidad 1 de 1st Year. Las próximas unidades y cursos usarán estructuras compartidas con nuevos contextos y mayor autonomía.')}</p></div></div></div>`;}
function examples(ex){return `<ul class="examples">${ex.map(([es,en])=>`<li><span class="spanish" lang="es">${es}</span>${state.mode!=='es'?`<span lang="en" class="secondary">${en}</span>`:''}</li>`).join('')}</ul>`;}
function referenceTable(t){return `<div class="reference-scroll"><table class="reference-table"><thead><tr>${t.headers.map(h=>`<th scope="col">${pair(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${row.map((c,i)=>`<${i===0?'th scope="row"':'td'}>${Array.isArray(c)?pair(c):`<span lang="es">${E(c)}</span>`}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function lessonHTML(l){return `<details class="lesson" id="lesson-${l.id}" data-lesson="${l.id}" ${state.lessonOpen===l.id?'open':''}><summary>${pair(l.title)}</summary><div class="lesson-body"><p class="lesson-intro">${teach(l.intro)}</p>${(l.paragraphs??[]).map(p=>`<p>${teach(p)}</p>`).join('')}${(l.tables??[]).map(referenceTable).join('')}<h3>${L('In conversation','En una conversación')}</h3>${examples(l.examples)}${l.note?`<div class="teaching-note"><p>${teach(l.note)}</p></div>`:''}${l.extra?.length?`<div class="optional-explanation">${button('learn-extra',pair([state.learnExtras.has(l.id)?'Less detail':'More detail · optional',state.learnExtras.has(l.id)?'Menos detalle':'Más detalle · opcional']),'ghost',`data-id="${l.id}" aria-expanded="${state.learnExtras.has(l.id)}" aria-controls="extra-${l.id}"`)}<div id="extra-${l.id}" ${state.learnExtras.has(l.id)?'':'hidden'}>${l.extra.map(p=>`<p>${teach(p)}</p>`).join('')}</div></div>`:''}<section class="checkpoint"><h3>${L('Quick check','Comprueba')}</h3><p>${pair(l.checkpoint.prompt)}</p>${button('learn-check',pair([state.learnChecks.has(l.id)?'Hide the answer':'Check',state.learnChecks.has(l.id)?'Ocultar la respuesta':'Comprobar']),'ghost',`data-id="${l.id}" aria-expanded="${state.learnChecks.has(l.id)}"`)}${state.learnChecks.has(l.id)?`<div class="feedback">${pair(l.checkpoint.answer)}</div>`:''}</section><section class="try-it"><h3>${L('Your turn','Tu turno')}</h3><p>${pair(l.tryIt)}</p><div class="flow-actions">${button('topic-practice',pair(['Practise this topic','Practicar este tema']),'primary ghost',`data-topic="${l.id}"`)}${['age','feelings'].includes(l.id)?button('lesson-lab',pair(['Try it in the lab','Pruébalo en el laboratorio']),'ghost',`data-kind="${l.id==='age'?'age':'feeling'}"`):''}${['alphabet','numbers'].includes(l.id)?button('lesson-vocab',pair(['Full reference','Referencia completa']),'ghost',`data-tab="${l.id}"`):''}</div></section></div></details>`;}
function readingHTML(r){return `<article class="panel reading"><h3>${pair(r.title)}</h3><p class="reading-text" lang="es">${E(r.text).replace(/\n/g,'<br>')}</p><p>${pair(r.task)}</p>${button('reading-check',pair([state.readingChecks.has(r.id)?'Hide the model answer':'Compare with a model answer',state.readingChecks.has(r.id)?'Ocultar la respuesta modelo':'Comparar con una respuesta modelo']),'ghost',`data-id="${r.id}" aria-expanded="${state.readingChecks.has(r.id)}"`)}${state.readingChecks.has(r.id)?`<div class="feedback">${pair(r.answer)}</div>`:''}</article>`;}
function learn(){return shell(pair(['Your first Spanish toolkit','Tus primeras herramientas de español']),`<p class="lead">${L('Choose a topic. Try the examples, then put them to use.','Elige un tema. Prueba los ejemplos y ponlos en práctica.')}</p>${state.helpReturn?`<div class="flow-actions">${button('back-task',pair(['Back to my activity','Volver a mi actividad']),'primary')}</div>`:''}<nav class="topic-index" aria-label="${E(T('Learning topics','Temas de aprendizaje'))}">${topics.map(([id,en,es],i)=>button('open-lesson',`${i+1}. ${pair([en,es])}`,'ghost',`data-id="${id}"`)).join('')}</nav><div class="two-col learn-layout"><div>${lessons.map(lessonHTML).join('')}<section class="section-title" id="reading-section"><p class="eyebrow">${T('Read and connect','Lee y relaciona')}</p><h2>${L('Three original reading texts','Tres textos originales de lectura')}</h2><p>${L('Read for meaning first. Then find the details and compare your answer. The mixed-practice bank also includes reading questions.','Lee primero para comprender. Después busca los detalles y compara tu respuesta. El banco de práctica también incluye preguntas de lectura.')}</p></section>${readingTexts.map(readingHTML).join('')}<section class="note-strip"><div><h3>${L('Hear it in a new context','Escúchalo en un contexto nuevo')}</h3><p>${L('Try the two listening tasks with the language you have learned.','Prueba las dos tareas de comprensión auditiva con lo que has aprendido.')}</p></div>${go('listening',pair(['Listen','Escuchar']),'primary')}</section><div class="flow-actions">${button('learn-done',pair(['I have worked through the learning blocks','He trabajado los bloques de aprendizaje']),'primary')}${go('explore',pair(['Next: explore','Siguiente: experimenta']),'primary ghost')}</div></div><aside><div class="panel tinted"><p class="section-label">${T('A model encounter','Un encuentro de ejemplo')}</p><h2>Alba + Inés</h2>${dialogue.map(([name,line])=>`<div class="dialogue-row"><strong>${name}</strong><span lang="es">${line}</span></div>`).join('')}<p class="small">${L('Two invented people. Change names, ages and greetings when you make your own exchange.','Dos personajes inventados. Cambia los nombres, edades y saludos al crear tu propio intercambio.')}</p></div><details class="panel study-route"><summary>${L('Suggested study route','Recorrido sugerido')}</summary><p class="small">${L('Twelve suggested stages: revisit, practise and communicate at each one. Your teacher can combine or extend them; this is not a timed course.','Doce etapas sugeridas: repasa, practica y comunícate en cada una. Tu profesor puede combinarlas o ampliarlas; no es un curso cronometrado.')}</p><ol class="session-route">${sessionRoute.map(([id,en,es,desc,desces])=>`<li>${button('open-lesson',pair([en,es]),'mini-button ghost',`data-id="${id}"`)}<p class="small">${L(desc,desces)}</p></li>`).join('')}</ol></details></aside></div>`);}
function questionIndices(){return questions.map((q,i)=>i).filter(i=>state.practiceTopic==='all'||questions[i].topic===state.practiceTopic);}
function choosePractice(topic){state.practiceTopic=topic;state.q=questionIndices()[0]??0;state.section='practise';if(parseRoute(location.hash).section==='practise')render({focus:true});else location.hash=unitHash('practise');}
function lab(){const kind=state.labKind;if(kind==='name'&&!['yo','tu','alba'].includes(state.labPerson))state.labPerson='yo';const person=state.labPerson;
 const vals=kind==='age'?['doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte']:kind==='name'?['Alba','Inés','Leo']:['bien','muy bien','fenomenal','regular','mal','fatal'];if(!vals.includes(state.labValue))state.labValue=vals[0];
 const sentence=labSentence(kind,person,state.labValue),verb=labForm(kind,person);
 const enExplain=kind==='age'?'Age uses tener. The full person pattern is tengo, tienes, tiene, tenemos, tenéis, tienen. The age can stay the same.':kind==='name'?'Me llamo, te llamas and se llama identify different people. Learn how the whole phrase works before learning the full system.':'Estar changes with the person: estoy, estás, está, estamos, estáis, están. Here we use it to say how someone is feeling.';
 const esExplain=kind==='age'?'La edad se expresa con tener. El patrón completo es tengo, tienes, tiene, tenemos, tenéis, tienen. La edad puede seguir siendo la misma.':kind==='name'?'Me llamo, te llamas y se llama identifican a diferentes personas. Aprende cómo funciona la expresión antes de estudiar todo el sistema.':'Estar cambia con la persona: estoy, estás, está, estamos, estáis, están. Aquí lo usamos para indicar cómo se encuentra alguien.';
 return `<div class="tab-label" role="group" aria-label="${E(T('Choose a pattern','Elige una estructura'))}">${[['age','Age','Edad'],['name','Name','Nombre'],['feeling','How someone feels','Cómo se encuentra alguien']].map(([id,en,es])=>button('lab-kind',pair([en,es]),state.labKind===id?'primary':'',`data-kind="${id}" aria-pressed="${state.labKind===id}"`)).join('')}</div><div class="two-col"><section class="panel"><p class="section-label">${T('Change one thing. Notice the difference.','Cambia algo y observa la diferencia.')}</p><div class="lab-controls"><div><label for="lab-person">${T('Who is the phrase about?','¿A quién se refiere la frase?')}</label><select id="lab-person">${[['yo','yo','the speaker','quien habla'],['tu','tú','one listener','una persona que escucha'],['alba',kind==='name'?'ella':'Alba','another person','otra persona'],...(kind==='name'?[]:[['nosotros','nosotros','our group','nuestro grupo'],['vosotros','vosotros','several listeners','varias personas que escuchan'],['ellos','ellos','another group','otro grupo']])].map(([id,label,en,es])=>`<option value="${id}" ${person===id?'selected':''}>${label} · ${T(en,es)}</option>`).join('')}</select></div><div><label for="lab-value">${T('Change the detail','Cambia el dato')}</label><select id="lab-value">${vals.map(v=>`<option ${state.labValue===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="output"><p class="lab-sentence" lang="es">${sentence.replace(verb,`<mark>${verb}</mark>`)}</p><p>${L(`Notice <strong>${verb}</strong>. Change the person while keeping the same detail.`,`Fíjate en <strong>${verb}</strong>. Cambia la persona y conserva el dato.`)}</p></div><p class="small" style="margin-top:18px">${L('In a question about the listener, you can use ¿Cuántos años tienes?, ¿Cómo te llamas? or ¿Cómo estás?','En una pregunta sobre quien escucha, puedes usar ¿Cuántos años tienes?, ¿Cómo te llamas? o ¿Cómo estás?')}</p></section><aside class="panel"><h3>${L('What is changing?','Qué está cambiando')}</h3><p>${L(enExplain,esExplain)}</p><p class="small">${L('The highlighted words show the change. Colour is an extra cue, not the only cue.','Las palabras destacadas muestran el cambio. El color es una ayuda adicional, no la única.')}</p>${button('lab-reset',pair(['Start with yo again','Vuelve a empezar con yo']),'ghost')}</aside></div><section class="panel"><h3>${L('Predict before you switch','Predice antes de cambiar')}</h3><p>${L('Leo is speaking to you. Complete his question.','Leo habla contigo. Completa su pregunta.')}</p><p class="question" lang="es">¿Cuántos años ___?</p><div class="chips">${['tengo','tienes','tiene'].map(v=>button('predict',v,state.predAnswer===v?'primary':'',`data-value="${v}" aria-pressed="${state.predAnswer===v}"`)).join('')}</div>${state.predChecked?`<div class="feedback ${state.predAnswer==='tienes'?'':'error'}"><strong>${state.predAnswer==='tienes'?T('That fits.','Encaja.'):T('Adjust the person.','Ajusta la persona.')}</strong><p>${L('Use tienes when asking the listener. You answer Tengo… años about yourself.','Usa tienes para preguntar a quien escucha. Respondes Tengo… años cuando hablas de ti.')}</p></div>`:''}<div class="flow-actions">${button('predict-check',pair(['Check my prediction','Comprueba mi predicción']),'primary')}${go('practise',pair(['Continue to practise','Continúa con la práctica']),'primary ghost')}</div></section>`;
}
function play(){return shell(pair(['Play · Choose your adventure','Play · Elige tu aventura']),renderPlay(state.play,{L,T,pair,button,E}));}
function explore(){return shell(pair(['Six ways to discover Spanish','Seis maneras de descubrir el español']),renderExplore(state.explore,{L,T,pair,button,E}));}
function practice(){const indices=questionIndices(),position=indices.indexOf(state.q),q=questions[state.q],value=state.qValues[q.id]??(q.type==='order'?[]:''),fb=state.qFeedback[q.id];let response='';
 if(q.type==='choice')response=`<div class="choices" role="group" aria-label="${E(T('Possible answers','Respuestas posibles'))}">${q.options.map((v,i)=>button('q-choice',`<span lang="es">${E(v)}</span>`,'choice',`data-value="${E(v)}" aria-pressed="${value===v}"`)).join('')}</div>`;
 else if(q.type==='text')response=`<label for="practice-answer">${T('Your answer','Tu respuesta')}</label><input class="input" id="practice-answer" autocomplete="off" value="${E(value)}" ${q.id==='q8'?'inputmode="numeric"':''}><div class="character-bank" role="group" aria-label="${E(T('Spanish characters','Caracteres del español'))}">${['á','é','í','ó','ú','ñ','¿','¡'].map(c=>button('insert-character',c,'mini-button',`data-value="${c}"`)).join('')}</div>`;
 else response=`<p class="small">${L('Select words in order. Use Undo or Clear if you want to change them.','Selecciona las palabras en orden. Usa Deshacer o Borrar para cambiarlas.')}</p><div class="token-answer" aria-label="${E(T('Your sentence','Tu frase'))}" lang="es">${value.length?value.map(i=>E(q.tokens[i])).join(' '):T('Your sentence appears here','Tu frase aparecerá aquí')}</div><div class="token-bank">${q.tokens.map((v,i)=>button('q-token',v,'',`data-index="${i}" ${value.includes(i)?'disabled':''}`)).join('')}</div><div class="flow-actions">${button('q-undo',pair(['Undo','Deshacer']),'ghost')}${button('q-clear',pair(['Clear','Borrar']),'ghost')}</div>`;
 return shell(pair(['Try a little. Learn a lot.','Prueba un poco y aprende mucho.']),`<p class="lead">${L(`${questions.length} activities organised by topic. Choose a short set or mix everything. Use hints, revisit an explanation and try again without a timer.`,`${questions.length} actividades organizadas por temas. Elige un bloque breve o mezcla los contenidos. Usa pistas, repasa una explicación y vuelve a intentarlo sin cronómetro.`)}</p><div class="practice-filter"><label for="practice-topic">${T('Choose your practice','Elige tu práctica')}</label><select id="practice-topic">${[['all','Mixed practice','Práctica combinada'],...topics,['reading','Reading','Lectura']].map(([id,en,es])=>`<option value="${id}" ${state.practiceTopic===id?'selected':''}>${T(en,es)} · ${id==='all'?questions.length:questions.filter(q=>q.topic===id).length}</option>`).join('')}</select></div><div class="two-col"><section class="panel"><p class="q-progress">${T('ACTIVITY','ACTIVIDAD')} ${position+1} / ${indices.length}</p><h2>${pair(q.prompt)}</h2>${q.reading?`<div class="reading-text" lang="es">${E(readingTexts.find(r=>r.id===q.reading).text).replace(/\n/g,'<br>')}</div>`:''}${q.stem?`<p class="question" lang="es">${q.stem}</p>`:''}<form id="practice-form">${response}<details class="hint"><summary>${T('A useful hint','Una pista útil')}</summary><p>${pair(q.hint)}</p></details>${fb?`<div class="feedback ${fb==='ok'?'':'error'}"><strong>${fb==='ok'?T('That works.','Funciona.'):T('A small adjustment','Un pequeño ajuste')}</strong><p>${pair(q.feedback)}</p></div>`:''}<div class="flow-actions"><button id="check-answer" class="primary" type="submit">${pair(['Check answer','Comprobar respuesta'])}</button>${button('q-next',pair([position===indices.length-1?'Review my practice':'Next activity',position===indices.length-1?'Revisar mi práctica':'Siguiente actividad']),'ghost')}</div></form></section><aside class="panel"><h3>${L('Useful, not perfect','Útil antes que perfecto')}</h3><p>${L('A wrong attempt is a clue about what to try next. Using a hint or English support never costs points.','Un intento incorrecto indica qué puedes probar después. Usar una pista o apoyo en inglés nunca resta puntos.')}</p><p>${L(`${state.qPractised.size} activities answered with a fitting response in this visit.`,`${state.qPractised.size} actividades respondidas de forma adecuada en esta visita.`)}</p>${button('refresh',pair(['Revisit this explanation','Repasar esta explicación']),'ghost')}<div class="flow-actions">${button('q-back',pair(['Previous activity','Actividad anterior']),'ghost')}</div></aside></div>`);}
function communicate(){const m=mission[state.missionAt],chosen=state.missionValues[m.id],fb=state.missionFeedback[m.id];return shell(pair(['The right person. The right meeting.','La persona correcta para el encuentro.']),`<p class="lead">${L('You are Alba, aged thirteen. Meet Inés and check the meeting list. Use invented details, not your personal information.','Eres Alba y tienes trece años. Conoce a Inés y comprueba la lista de encuentros. Usa datos inventados, no tu información personal.')}</p><div class="mission-cards"><section class="panel tinted"><p class="section-label">${T('Your fictional identity','Tu identidad ficticia')}</p><h2>Alba · 13</h2><p lang="es">Me llamo Alba.<br>Tengo trece años.</p><p>${L('Your purpose: ask for a name and age, check the spelling, and choose the correct meeting card.','Tu propósito: preguntar un nombre y una edad, comprobar las letras y elegir la tarjeta de encuentro correcta.')}</p></section><section class="panel"><p class="section-label">${T('The list needs checking','Hay que comprobar la lista')}</p><h3>${L('Which meeting card is right?','Qué tarjeta de encuentro es correcta')}</h3><ul class="mission-list"><li><strong>A</strong> Inés · 13</li><li><strong>B</strong> Inés · 14</li><li><strong>C</strong> Iris · 14</li></ul><p class="small">${L('Find the missing information in the encounter below.','Busca la información que falta en el encuentro de abajo.')}</p></section></div><section class="panel"><p class="q-progress">${T('GUIDED ENCOUNTER','ENCUENTRO GUIADO')} ${state.missionAt+1} / ${mission.length}</p><p class="eyebrow">${m.speaker}</p><p class="question" lang="es">${m.line}</p><p>${L('Choose what you would say as Alba.','Elige lo que dirías como Alba.')}</p><div class="choices">${m.options.map(v=>button('m-choice',`<span lang="es">${v}</span>`,'choice',`data-value="${E(v)}" aria-pressed="${chosen===v}"`)).join('')}</div>${fb?`<div class="feedback ${fb==='ok'?'':'error'}"><strong>${fb==='ok'?T('The conversation can move on.','La conversación puede continuar.'):T('Check the purpose of this turn.','Comprueba el propósito de este turno.')}</strong><p>${pair(m.feedback)}</p></div>`:''}<div class="flow-actions">${button('m-check',pair(['Try this reply','Prueba esta respuesta']),'primary')}${button('m-next',pair(['Next part','Siguiente parte']),'ghost')}${button('m-back',pair(['Previous part','Parte anterior']),'ghost')}</div></section><section class="panel" id="meeting-final"><h2>${L('Now help Inés find her meeting','Ahora ayuda a Inés a encontrar su encuentro')}</h2><p>${L('Choose the card that matches her name and age. You can go back to check the encounter.','Elige la tarjeta que coincide con su nombre y edad. Puedes volver al encuentro para comprobarlo.')}</p><div class="chips">${['A','B','C'].map(v=>button('meeting-choice',`${v} · ${v==='C'?'Iris':'Inés'} · ${v==='A'?'13':'14'}`,state.meetingChoice===v?'primary':'',`data-value="${v}" aria-pressed="${state.meetingChoice===v}"`)).join('')}</div><div class="flow-actions">${button('meeting-check',pair(['Check the meeting','Comprueba el encuentro']),'primary')}</div>${state.meetingChecked?`<div class="feedback ${state.meetingChoice==='B'?'':'error'}"><strong>${state.meetingChoice==='B'?T('Card B matches.','La tarjeta B coincide.'):T('Check both details.','Comprueba los dos datos.')}</strong><p>${L('Inés says her name is Inés and that she is fourteen. Card B matches both.','Inés dice que se llama Inés y que tiene catorce años. La tarjeta B coincide con ambos datos.')}</p></div>`:''}</section>${communicationTasks.map(t=>`<section class="panel"><h2>${pair(t.title)}</h2><p>${pair(t.instructions)}</p><p class="teaching-note"><strong>${T('Your outcome: ','Tu resultado: ')}</strong>${pair(t.outcome)}</p></section>`).join('')}<section class="panel"><h2>${L('Make the encounter your own','Haz tu propio encuentro')}</h2><p>${L('With a partner, use two invented identities. Ask for two details, check one and finish the conversation. Alone, write both sides of a short exchange.','Con un compañero, usa dos identidades inventadas. Pregunta dos datos, comprueba uno y termina la conversación. Si estás solo, escribe las dos partes de un intercambio breve.')}</p><label for="draft">${T('Optional private writing space','Espacio de escritura privada opcional')}</label><textarea class="input" id="draft" placeholder="Hola…">${E(state.draft)}</textarea><p class="small">${L('Your writing stays in memory on this page. It is not saved in practice history, uploaded or automatically graded. Copy or download it before reloading or closing.','Tu texto permanece en memoria en esta página. No se guarda en el historial, no se envía y no se califica automáticamente. Cópialo o descárgalo antes de recargar o cerrar.')}</p><div class="flow-actions">${button('download',pair(['Download my writing','Descargar mi texto']),'ghost')}${button('print',pair(['Print this task','Imprimir esta tarea']),'ghost')}</div><div class="checklist">${[['greet','I opened and closed the conversation.','He empezado y terminado la conversación.'],['details','I asked for a name and age.','He preguntado el nombre y la edad.'],['repair','I checked a detail or asked for help.','He comprobado un dato o pedido ayuda.']].map(([id,en,es])=>`<label><input type="checkbox" data-self="${id}" ${state.checks[id]?'checked':''}><span>${L(en,es)}</span></label>`).join('')}</div><label for="reflection">${T('One thing I can now do, or want to revisit','Algo que ya puedo hacer o que quiero repasar')}</label><textarea class="input" id="reflection" style="min-height:90px">${E(state.reflection)}</textarea><div class="flow-actions">${button('mission-complete',pair(['I have tried the communication task','He realizado la tarea comunicativa']),'primary')}</div><p class="notice">${L('The checklist is your reflection. Open writing and speaking need self, peer or teacher review; this page does not certify your Spanish level.','La lista recoge tu reflexión. La escritura y la conversación libres necesitan autoevaluación o revisión de un compañero o del profesor; esta página no certifica tu nivel de español.')}</p></section>`);}
function vocabulary(){const search=state.vocabSearch.toLocaleLowerCase('es'),filtered=phrases.filter(p=>`${p[1]} ${p[2]}`.toLocaleLowerCase('es').includes(search));let body='';
 if(state.vocabTab==='phrases')body=`<label for="vocab-search">${T('Find an expression','Busca una expresión')}</label><input id="vocab-search" class="input" type="search" value="${E(state.vocabSearch)}" placeholder="${E(T('Name, age, help…','Nombre, edad, ayuda…'))}"><div class="vocab-grid" style="margin-top:24px">${filtered.map(([id,es,en,note])=>`<article class="vocab-card"><p class="spanish" lang="es">${es}</p><small>${state.mode!=='es'?`<span lang="en">${E(en)}</span>`:''}</small><small>${pair(note)}</small>${button('speak',pair(['Listen','Escuchar']),'mini-button',`data-phrase="${E(es)}"`)}</article>`).join('')||`<p>${L('No matches. Try a shorter search.','No hay coincidencias. Prueba una búsqueda más breve.')}</p>`}</div>`;
 else if(state.vocabTab==='numbers')body=`<div class="number-grid">${numbers.map((n,i)=>button('speak',`<b>${i}</b><span lang="es">${n}</span>`,'',`data-phrase="${n}"`)).join('')}</div>`;
 else body=`<p>${L('Select a letter to hear its name if your device has a local Spanish voice. The ñ is a separate letter. Ch and ll are combinations of letters, not extra alphabet entries.','Selecciona una letra para oír su nombre si tu dispositivo tiene una voz local en español. La ñ es una letra. Ch y ll son combinaciones de letras, no entradas adicionales del alfabeto.')}</p><div class="alphabet-grid">${alphabet.map(([letter,name])=>button('speak',`<span class="letter" lang="es">${letter}</span><small lang="es">${name}</small>`,'',`data-phrase="${name}"`)).join('')}</div>`;
 return shell(pair(['Words for your next conversation','Palabras para tu próxima conversación']),`<p class="lead">${L('A small, useful collection. Try hiding the English meaning and recalling it before you look.','Una colección pequeña y útil. Intenta recordar el significado antes de mirar el apoyo en inglés.')}</p><div class="tab-label">${[['phrases','Expressions','Expresiones'],['numbers','Numbers 0–20','Números 0–20'],['alphabet','Alphabet','Alfabeto']].map(([id,en,es])=>button('vocab-tab',pair([en,es]),state.vocabTab===id?'primary':'',`data-tab="${id}" aria-pressed="${state.vocabTab===id}"`)).join('')}</div>${body}${state.audioNotice?`<p class="feedback">${L('No local Spanish voice is available. Use the written model or practise with your teacher.','No hay una voz local en español disponible. Usa el modelo escrito o practica con tu profesor.')}</p>`:''}${state.helpReturn?`<div class="flow-actions">${button('back-task',pair(['Back to my task','Volver a mi tarea']),'primary')}</div>`:''}<p class="notice" style="margin-top:28px">${L('Listen uses a local Spanish device voice when available. No recording or microphone is used. If a local voice is unavailable, read the text or practise with your teacher.','Escuchar usa una voz local del dispositivo en español cuando está disponible. No se graba ni se usa el micrófono. Si no hay voz local, lee el texto o practica con tu profesor.')}</p>`,{step:false});}
function listening(){return shell(pair(['Listen. Catch a little more each time.','Escucha y descubre un poco más cada vez.']),`<p class="lead">${L('Two short recordings. Listen first, then complete the details. Replay as often as you need; the transcript is there when you want support.','Dos grabaciones breves. Escucha primero y completa después los datos. Repite cuando lo necesites; puedes consultar la transcripción como apoyo.')}</p><nav class="flow-actions" aria-label="${E(T('Listening recordings','Grabaciones de comprensión auditiva'))}">${listenings.map(l=>button('audio-jump',pair(l.title),'ghost',`data-id="${l.id}"`)).join('')}</nav>${listenings.map(l=>`<section class="panel listening-card" id="audio-${l.id}"><p class="eyebrow">${T('Listen and understand','Escucha y comprende')}</p><h2>${pair(l.title)}</h2><p>${pair(l.focus)}</p><p>${pair(l.instructions)}</p><audio id="player-${l.id}" data-listening="${l.id}" controls preload="none" aria-label="${E(T(...l.title))}" src="${l.file}">${L('Your browser cannot play this audio. Use the download link.','Tu navegador no puede reproducir este audio. Usa el enlace de descarga.')}</audio><div class="audio-caption"><span>${L('Slow pace · pauses included','Ritmo pausado · con pausas')}</span><a href="${l.file}" download>${L('Download audio','Descargar audio')}</a></div><div class="listening-grid">${l.questions.map((q,i)=>`<div class="listening-question"><label for="${q.id}">${i+1}. ${pair(q.prompt)}</label><select id="${q.id}" data-listening-question="${q.id}" data-recording="${l.id}"><option value="">${T('Choose…','Elige…')}</option>${q.options.map(v=>`<option value="${E(v)}" ${state.listeningAnswers[q.id]===v?'selected':''} lang="es">${E(v)}</option>`).join('')}</select>${state.listeningChecked.has(l.id)?`<div class="feedback ${state.listeningAnswers[q.id]===q.answer?'':'error'}"><strong>${state.listeningAnswers[q.id]===q.answer?T('That fits.','Encaja.'):state.listeningAnswers[q.id]?T('Listen for this detail.','Escucha este dato.'):T('Try this detail next.','Prueba con este dato.')}</strong><p>${pair(q.feedback)}</p></div>`:''}</div>`).join('')}</div><div class="flow-actions">${button('listening-check',pair(['Check my answers','Comprobar mis respuestas']),'primary',`data-id="${l.id}"`)}${button('listening-transcript',pair([state.listeningTranscripts.has(l.id)?'Hide transcript':'Show transcript',state.listeningTranscripts.has(l.id)?'Ocultar transcripción':'Ver transcripción']),'ghost',`data-id="${l.id}" aria-expanded="${state.listeningTranscripts.has(l.id)}" aria-controls="transcript-${l.id}"`)}</div><div id="transcript-${l.id}" ${state.listeningTranscripts.has(l.id)?'':'hidden'}><h3>${L('Transcript','Transcripción')}</h3>${l.transcript.map(([speaker,text])=>`<div class="dialogue-row"><strong>${speaker}</strong><span lang="es">${text}</span></div>`).join('')}</div></section>`).join('')}<p class="notice">${L('Original scripts · Synthetic voices created with ElevenLabs · No student audio is recorded or sent.','Guiones originales · Voces sintéticas creadas con ElevenLabs · No se graba ni se envía audio del alumnado.')}</p>`,{step:true});}
function grammar(){return shell(pair(['A pattern you can use anywhere','Una estructura para distintos contextos']),`<p class="lead">${L('This shared lab uses the context of your current unit. You can revisit it whenever it helps.','Este laboratorio compartido usa el contexto de tu unidad. Puedes volver siempre que te ayude.')}</p>${lab()}${state.helpReturn?`<div class="flow-actions">${button('back-task',pair(['Back to my task','Volver a mi tarea']),'primary')}</div>`:''}`,{step:false});}
function render({focus=false}={}){
 for(const audio of main.querySelectorAll?.('audio[data-listening]')??[])state.audioPositions[audio.dataset.listening]={time:audio.currentTime,rate:audio.playbackRate,volume:audio.volume,muted:audio.muted,playing:!audio.paused&&!focus};
 const active=document.activeElement,hadFocus=main.contains(active),focusId=active?.id;
 const attrs=['action','value','kind','tab','phrase','index','id','topic'];
 const focusData=hadFocus&&active?.dataset?Object.fromEntries(attrs.filter(k=>k in active.dataset).map(k=>[k,active.dataset[k]])):null;
 const selection=hadFocus&&typeof active.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null;
 document.documentElement.lang=state.mode==='es'?'es':'en';document.documentElement.classList.toggle('large-text',state.large);$('#mode').value=state.mode;
 $('#nav').innerHTML=route.kind==='unit'&&route.unit==='2'?go('home',pair(['Courses','Cursos']))+go(courseHash('1st-year'),'1st Year')+go(unitHash('overview','1st-year','2'),'Unit 2')+go(unitHash('learn','1st-year','2'),pair(['Learn','Aprende']),state.section==='learn'?'current':''):route.kind==='unit'?[['home','Courses','Cursos'],['unit','Unit 1','Unidad 1'],['grammar','Grammar','Gramática'],['vocabulary','Vocabulary','Vocabulario'],['listening','Listening','Escucha'],['play','Play','Juega']].map(([id,en,es])=>go(id,pair([en,es]),state.section===id?'current':'')).join(''):go('home',pair(['Courses','Cursos']),route.kind==='home'?'current':'');
 // Unit-specific views are registered once; the catalogue and routing stay shared.
 const runtimes={unit1:{unit:unitHome,learn,explore,play,practise:practice,communicate,grammar,vocabulary,listening},unit2:{unit:()=>renderUnit2Overview({L}).replaceAll('href="#course/1st-year/unit/2/learn"','href="#course/1st-year/unit/2/learn" data-action="u2b-back"')+`<section class="page"><div class="panel"><p class="eyebrow">Learn · B</p><h2 lang="es">Mi semana escolar</h2><p>${L('Discover days, subjects, a school timetable and preferences.','Descubre días, asignaturas, un horario escolar y preferencias.')}</p><a class="primary" href="#course/1st-year/unit/2/learn" data-action="u2b-open">${L('Open Block B','Abrir el Bloque B')}</a></div></section>`+renderJourneyOverviewCard({L}),learn:()=>renderUnit2LearnSwitch({L,button,week:weekState,journey:journeyState})+(journeyState.open?renderUnit2Journey({L,T,E,button,state:{...journeyState,mode:state.mode}}):weekState.open?renderUnit2Week({L,T,E,button,state:{...weekState,mode:state.mode}}):renderUnit2Learn({L,T,E,button,state:{...state.unit2,mode:state.mode}}))}};
 const views=route.kind==='unit'?runtimes[findUnit(route.course,route.unit,route.level).runtime]:{};
 const html=route.kind==='home'?home():route.kind==='course'?courseHome():(views[state.section]??unitHome)();
 // Keep the approved Explore renderer intact; scope its onward link to U1.
 main.innerHTML=route.kind==='unit'?html.replace('href="#practise"',`href="#${unitHash('practise')}"`):html;
 for(const audio of main.querySelectorAll?.('audio[data-listening]')??[]){const saved=state.audioPositions[audio.dataset.listening];if(saved){try{audio.currentTime=saved.time;}catch{audio.addEventListener('loadedmetadata',()=>{audio.currentTime=saved.time;},{once:true});}audio.playbackRate=saved.rate;audio.volume=saved.volume;audio.muted=saved.muted;if(saved.playing)audio.play()?.catch(()=>{});}}
 document.title=`${route.kind==='home'?'Unas Tapitas de Español':route.kind==='course'?T(...findCourse(route.course).title)+(route.level?' · '+route.level.toUpperCase():''):T(route.unit==='2'?'Unit 2':'Unit 1',route.unit==='2'?'Unidad 2':'Unidad 1')+' · '+findUnit(route.course,route.unit)?.title} · Orilla`;
 $('#footer').innerHTML=`<p>Unas Tapitas de Español · Orilla</p><p>${L('Original materials · No accounts · No personal profiles','Materiales originales · Sin cuentas · Sin perfiles personales')}</p>${button('privacy',pair(['Privacy & help','Privacidad y ayuda']),'mini-button ghost')}`;
 if(focus){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
 else if(hadFocus){let target=focusId?document.getElementById(focusId):null;
 if(!target&&focusData&&Object.keys(focusData).length)target=[...main.querySelectorAll('[data-action]')].find(el=>!el.disabled&&Object.entries(focusData).every(([k,v])=>el.dataset[k]===v));
 if(!target&&active?.dataset?.action==='q-token')target=main.querySelector('.token-bank button:not(:disabled)')??document.getElementById('check-answer');
 (target??main).focus({preventScroll:true});if(target&&selection&&target.setSelectionRange)try{target.setSelectionRange(...selection);}catch{}
 }save();
}
function openOptions(privacy=false){$('#options-title').innerHTML=pair(privacy?['Privacy and practical help','Privacidad y ayuda práctica']:['Make this space work for you','Ajusta este espacio a tu manera']);
 $('#options-content').innerHTML=`<div class="settings-row"><label><input id="large-text" type="checkbox" ${state.large?'checked':''}><span>${L('Larger text','Texto más grande')}</span></label></div><div class="settings-row"><label><input id="save-progress" type="checkbox" ${state.saving?'checked':''}><span>${L('Remember practice on this device','Recordar la práctica en este dispositivo')}</span></label><small>${L('Optional. On shared school computers, leave this off. Saves language, last section, practice sections and game checkpoints with fictional characters; never your writing or personal identity.','Opcional. En ordenadores escolares compartidos, déjalo desactivado. Guarda idioma, último apartado, apartados practicados y puntos de juego con personajes ficticios; nunca tu texto ni identidad personal.')}</small></div><p class="small">${L('Saved practice belongs to this browser, not a student account. Another user of the same browser could see it. It does not sync between devices and may be removed by browser settings.','La práctica guardada pertenece a este navegador, no a una cuenta de alumno. Otra persona que use el mismo navegador podría verla. No se sincroniza entre dispositivos y el navegador puede borrarla.')}</p>${state.storageError?`<p class="error-text">${L('This browser could not read or save practice. All learning activities still work.','Este navegador no ha podido leer o guardar la práctica. Todas las actividades siguen disponibles.')}</p>`:''}${button('forget',pair(['Forget saved practice on this device','Borrar la práctica guardada en este dispositivo']),'ghost')}<h3 style="margin-top:25px">${L('What this prototype does','Qué hace este prototipo')}</h3><p class="small">${L('No microphone, recording, analytics or automatic grading of open writing. Closed activities check answers locally. Unit 1 vocabulary uses a local Spanish device voice; Unit 2 Learn A uses saved MP3 recordings. Listening tasks use saved recordings. Hosting providers may process technical requests needed to serve the site.','No usa micrófono, grabación, analítica ni calificación automática de escritura libre. Las actividades cerradas comprueban las respuestas localmente. El vocabulario de la Unidad 1 usa una voz local en español; Learn A de la Unidad 2 usa MP3 guardados. Los listenings usan grabaciones guardadas. El alojamiento puede tratar las peticiones técnicas necesarias para servir el sitio.')}</p><p class="small">${L('Before closing or reloading, download any writing you want to keep. With saving off, practice ends when you leave.','Antes de cerrar o recargar, descarga el texto que quieras conservar. Sin guardado, la práctica termina cuando sales.')}</p>`;
 $('#close-options').innerHTML=pair(['Done','Listo']);$('#options').showModal();
}
function speak(text){const voice=window.speechSynthesis?.getVoices().find(v=>v.localService&&/^es(?:[-_]|$)/i.test(v.lang));if(!voice){state.audioNotice=true;render();announce('No local Spanish voice is available on this device. The written model is still here.','Este dispositivo no tiene una voz local en español disponible. El modelo escrito sigue disponible.');return;}const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang=voice.lang;u.rate=.85;window.speechSynthesis.cancel();window.speechSynthesis.speak(u);}
function checkPractice(){const q=questions[state.q],raw=state.qValues[q.id]??'',val=q.type==='order'?(Array.isArray(raw)?raw.map(i=>q.tokens[i]).join(' '):''):raw;if(!String(val).trim()){announce('Choose or write an answer first.','Primero elige o escribe una respuesta.');return;}const ok=check(q,val);state.qAttempted.add(q.id);state.qFeedback[q.id]=ok?'ok':'again';if(ok)state.qPractised.add(q.id);render();announce(ok?'That response fits.':'Read the explanation and try another response.',ok?'La respuesta encaja.':'Lee la explicación y prueba otra respuesta.');}
function download(){const text=`Hola y bienvenidos · My invented encounter / Mi encuentro inventado\n\n${state.draft}\n\nReflection / Reflexión\n${state.reflection}\n\nThis writing has not been automatically graded. / Este texto no se ha calificado automáticamente.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='mi-encuentro.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function onAction(e){const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action.startsWith('u2c-')){if(updateJourneyState(journeyState,action,b.dataset.value)){if(['u2c-open','u2c-stage','u2c-arrival','u2c-transport','u2c-walking','u2c-say-intent','u2c-say-step'].includes(action))for(const audio of main.querySelectorAll?.('audio[data-journey-audio]')??[])audio.pause?.();render();if(['u2c-arrival','u2c-transport','u2c-walking'].includes(action))$('#u2c-mode-audio')?.play?.()?.catch?.(()=>{});if(action==='u2c-stage'){$('#u2c-title')?.focus?.({preventScroll:true});$('#u2c-title')?.scrollIntoView?.({block:'start'});}announce(action==='u2c-answer'?(journeyState.answer==='walk'?'That matches Marcos’s journey.':'Listen again and try another picture.'):'Journey discovery updated.',action==='u2c-answer'?(journeyState.answer==='walk'?'Coincide con el trayecto de Marcos.':'Escucha de nuevo y prueba otra imagen.'):'Descubrimiento del trayecto actualizado.');}return;}
 if(action.startsWith('u2b-')){if(updateWeekState(weekState,action,b.dataset.value)){if(['u2b-open','u2b-back'].includes(action))journeyState.open=false;render();const player=action==='u2b-day'?$('#u2b-day-audio'):['u2b-subject','u2b-cell'].includes(action)?$('#u2b-subject-audio'):null;player?.play?.()?.catch?.(()=>{});if(action==='u2b-stage'){$('#u2b-title')?.focus?.({preventScroll:true});$('#u2b-title')?.scrollIntoView?.({block:'start'});}announce('School week updated. Read the current discovery.','Semana escolar actualizada. Lee el descubrimiento actual.');}return;}
 if(action.startsWith('u2-')){if(updateUnit2State(state.unit2,action,b.dataset.value)){render();if(action==='u2-object'||action==='u2-phrase'){const item=action==='u2-object'?unit2Objects.find(o=>o.id===b.dataset.value):unit2Expressions.find(p=>p.id===b.dataset.value);const player=$(action==='u2-object'?'#u2-object-audio':'#u2-phrase-audio');player?.play?.()?.catch?.(()=>{});announce(action==='u2-object'?`Now listening: ${item.name}`:`Now listening: ${item.text}`,action==='u2-object'?`Ahora escuchas: ${item.name}`:`Ahora escuchas: ${item.text}`);}}return;}
 if(action.startsWith('pg-')){const value=action==='pg-alien-send'?state.play.alien.tokens.map(i=>alienPieces[i]).join(' '):b.dataset.value;if(updatePlay(state.play,action,value)){render();if(state.play.notice)announce(...state.play.notice);else announce('Game updated. Read the current scene.','Juego actualizado. Lee la escena actual.');if(['pg-open','pg-menu','pg-restart','pg-work-next','pg-room','pg-alien-person'].includes(action)){main.focus({preventScroll:true});}}return;}
 if(action==='audio-jump'){$('#audio-'+b.dataset.id).scrollIntoView({block:'start'});$('#player-'+b.dataset.id).focus({preventScroll:true});return;}
 if(action==='listening-check'){const l=listenings.find(l=>l.id===b.dataset.id);state.listeningChecked.add(l.id);render();const n=l.questions.filter(q=>state.listeningAnswers[q.id]===q.answer).length;announce(`${n} details match. Feedback is shown beside each answer.`,`${n} datos coinciden. Cada respuesta tiene su explicación.`);return;}
 if(action==='listening-transcript'){state.listeningTranscripts.has(b.dataset.id)?state.listeningTranscripts.delete(b.dataset.id):state.listeningTranscripts.add(b.dataset.id);render();return;}
 if(action==='options'||action==='privacy'){openOptions(action==='privacy');return;}
 if(action==='learn-extra'){state.learnExtras.has(b.dataset.id)?state.learnExtras.delete(b.dataset.id):state.learnExtras.add(b.dataset.id);render();return;}
 if(action==='learn-check'||action==='reading-check'){const set=action==='learn-check'?state.learnChecks:state.readingChecks;set.has(b.dataset.id)?set.delete(b.dataset.id):set.add(b.dataset.id);render();return;}
 if(action==='open-lesson'){state.lessonOpen=b.dataset.id;render();$('#lesson-'+b.dataset.id).scrollIntoView({block:'start'});$('#lesson-'+b.dataset.id+' summary').focus({preventScroll:true});return;}
 if(action==='topic-practice'){choosePractice(b.dataset.topic);return;}
 if(action==='lesson-lab'){state.explore.lab='person';state.explore.personKind=b.dataset.kind==='feeling'?'feeling':'age';state.explore.personDetail=state.explore.personKind==='age'?'trece':'bien';location.hash=unitHash('explore');return;}
 if(action==='lesson-vocab'){state.vocabTab=b.dataset.tab;location.hash=unitHash('vocabulary');return;}
 if(action==='insert-character'){const el=$('#practice-answer'),q=questions[state.q],value=String(state.qValues[q.id]??''),start=el.selectionStart??value.length,end=el.selectionEnd??start;state.qValues[q.id]=value.slice(0,start)+b.dataset.value+value.slice(end);delete state.qFeedback[q.id];render();const next=$('#practice-answer');next.focus();next.setSelectionRange(start+1,start+1);return;}
 if(action==='speak'){speak(b.dataset.phrase);return;}
 if(action==='learn-done'){complete('learn');render();announce('Models marked as explored. You can revisit them any time.','Modelos marcados como explorados. Puedes volver cuando quieras.');return;}
 if(action==='lab-kind'){state.labKind=b.dataset.kind;state.labValue='';render();return;}
 if(action==='lab-reset'){state.labPerson='yo';render();return;}
 if(action==='predict'){state.predAnswer=b.dataset.value;state.predChecked=false;render();return;}
 if(action==='predict-check'){if(!state.predAnswer){announce('Choose a prediction first.','Primero elige una predicción.');return;}state.predChecked=true;if(state.predAnswer==='tienes')complete('explore');render();announce('Your prediction has feedback below.','Tu predicción tiene feedback debajo.');return;}
 if(action==='ex-done'){complete('explore');render();announce('Explore marked as visited. You can return to any laboratory.','Explore marcado como visitado. Puedes volver a cualquier laboratorio.');return;}
 if(action.startsWith('ex-')&&updateExplore(state.explore,action,b.dataset.value)){render();if(action.startsWith('ex-q-'))announceQuestionExperiment();if(action==='ex-lab'){$('#ex-stage').scrollIntoView({block:'start'});$('#ex-stage').focus({preventScroll:true});}return;}
 if(action==='q-choice'){const q=questions[state.q];state.qValues[q.id]=b.dataset.value;delete state.qFeedback[q.id];render();return;}
 if(action==='q-token'){const q=questions[state.q];state.qValues[q.id]??=[];state.qValues[q.id].push(Number(b.dataset.index));delete state.qFeedback[q.id];render();return;}
 if(action==='q-clear'||action==='q-undo'){const q=questions[state.q];state.qValues[q.id]??=[];action==='q-clear'?state.qValues[q.id]=[]:state.qValues[q.id].pop();delete state.qFeedback[q.id];render();return;}
 if(action==='q-next'){const indices=questionIndices(),pos=indices.indexOf(state.q);if(pos===indices.length-1){if(state.qAttempted.size===questions.length)complete('practise');route=parseRoute(unitHash());state.section='unit';location.hash=unitHash();render({focus:true});announce(`${state.qAttempted.size} of ${questions.length} activities attempted. Choose another topic whenever it helps.`,`${state.qAttempted.size} de ${questions.length} actividades intentadas. Elige otro tema cuando te ayude.`);}else{state.q=indices[pos+1];render();$('#practice-form').closest('section').scrollIntoView({block:'start'});}return;}
 if(action==='q-back'){const indices=questionIndices();state.q=indices[Math.max(0,indices.indexOf(state.q)-1)];render();return;}
 if(action==='refresh'){state.helpReturn=state.section;const q=questions[state.q];state.lessonOpen=q.topic==='reading'?'names':q.topic;location.hash=unitHash('learn');return;}
 if(action==='back-task'){location.hash=unitHash(state.helpReturn??'practise');state.helpReturn=null;return;}
 if(action==='m-choice'){state.missionValues[mission[state.missionAt].id]=b.dataset.value;delete state.missionFeedback[mission[state.missionAt].id];render();return;}
 if(action==='m-check'){const m=mission[state.missionAt],v=state.missionValues[m.id];if(!v){announce('Choose a reply first.','Primero elige una respuesta.');return;}const ok=v===m.answer;state.missionFeedback[m.id]=ok?'ok':'again';if(ok)state.missionDone.add(m.id);render();announce('Feedback is shown for this reply.','Se muestra el feedback de esta respuesta.');return;}
 if(action==='m-next'||action==='m-back'){state.missionAt=Math.max(0,Math.min(mission.length-1,state.missionAt+(action==='m-next'?1:-1)));render();return;}
 if(action==='meeting-choice'){state.meetingChoice=b.dataset.value;state.meetingChecked=false;render();return;}
 if(action==='meeting-check'){if(!state.meetingChoice){announce('Choose a meeting card first.','Primero elige una tarjeta de encuentro.');return;}state.meetingChecked=true;render();$('#meeting-final').scrollIntoView({block:'start'});announce('The meeting choice has feedback.','La elección del encuentro tiene feedback.');return;}
 if(action==='mission-complete'){complete('communicate');render();announce('Your communication practice is recorded. This is not an automatic language grade.','Se ha registrado tu práctica comunicativa. No es una nota automática de lengua.');return;}
 if(action==='vocab-tab'){state.vocabTab=b.dataset.tab;render();return;}
 if(action==='download'){download();return;}if(action==='print'){window.print();return;}
 if(action==='forget'){try{forgetProgress(localStorage);state.storageError=false;}catch{state.storageError=true;}state.saving=false;state.completed.clear();$('#options').close();render();announce('Saved practice has been forgotten on this device.','Se ha borrado la práctica guardada en este dispositivo.');}
}
document.body.addEventListener('click',onAction);
document.body.addEventListener('submit',e=>{if(e.target.id==='practice-form'){e.preventDefault();checkPractice();}});
main.addEventListener('input',e=>{const el=e.target;if(el.id==='practice-answer'){state.qValues[questions[state.q].id]=el.value;delete state.qFeedback[questions[state.q].id];}if(el.id==='draft')state.draft=el.value;if(el.id==='reflection')state.reflection=el.value;if(el.id==='vocab-search'){state.vocabSearch=el.value;const pos=el.selectionStart;render();const n=$('#vocab-search');n.focus();n.setSelectionRange(pos,pos);}});
main.addEventListener('change',e=>{if(e.target.dataset?.listeningQuestion){state.listeningAnswers[e.target.dataset.listeningQuestion]=e.target.value;if(state.listeningChecked.has(e.target.dataset.recording)){state.listeningChecked.delete(e.target.dataset.recording);render();}return;}if(e.target.id==='practice-topic'){choosePractice(e.target.value);return;}if(e.target.id?.startsWith('ex-')&&updateExplore(state.explore,e.target.id,e.target.value)){render();if(e.target.id.startsWith('ex-q-')){announceQuestionExperiment();return;}announce('The scene has changed. Explore the new result.','La escena ha cambiado. Explora el resultado.');return;}if(e.target.id==='lab-person'){state.labPerson=e.target.value;render();announce('The phrase has changed. Read the highlighted form.','La frase ha cambiado. Lee la forma destacada.');}if(e.target.id==='lab-value'){state.labValue=e.target.value;render();announce('The detail in the phrase has changed.','Ha cambiado el dato de la frase.');}if(e.target.dataset.self)state.checks[e.target.dataset.self]=e.target.checked;});
main.addEventListener('play',e=>{if(e.target.matches?.('audio[data-journey-audio]'))for(const audio of main.querySelectorAll?.('audio[data-journey-audio]')??[])if(audio!==e.target)audio.pause?.();},true);
main.addEventListener('toggle',e=>{if(e.target.matches('details[data-lesson]')&&e.target.open)state.lessonOpen=e.target.dataset.lesson;},true);
main.addEventListener('play',e=>{if(e.target.matches?.('audio[data-journey-audio]'))for(const audio of main.querySelectorAll?.('audio[data-journey-audio]')??[])if(audio!==e.target)audio.pause?.();},true);
main.addEventListener('toggle',e=>{if(e.target.id==='u2b-ideal')weekState.idealOpen=e.target.open;},true);
main.addEventListener('error',e=>{if(e.target.matches?.('audio[data-explore-audio]')||e.target.matches?.('audio#u2-object-audio, audio#u2-phrase-audio')||e.target.matches?.('audio[data-week-audio]')||e.target.matches?.('audio[data-journey-audio]')){e.target.hidden=true;e.target.nextElementSibling.hidden=false;}},true);
$('#mode').addEventListener('change',e=>{state.mode=e.target.value;render();announce('Language changed. Your current work is still here.','Idioma cambiado. Tu trabajo actual sigue aquí.');});
$('#settings').addEventListener('click',()=>openOptions());
$('#options').addEventListener('change',e=>{if(e.target.id==='large-text'){state.large=e.target.checked;document.documentElement.classList.toggle('large-text',state.large);}if(e.target.id==='save-progress'){state.saving=e.target.checked;if(!state.saving){try{forgetProgress(localStorage);}catch{state.storageError=true;}}else save();}});
$('#options').addEventListener('close',()=>render());
function applyRoute(){route=parseRoute(location.hash);if(location.hash!=='#'+routeHash(route))window.history?.replaceState(null,'','#'+routeHash(route));state.section=route.kind==='unit'?(route.section==='overview'?'unit':route.section):route.kind;}
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus({preventScroll:true});return;}applyRoute();render({focus:true});if(state.section==='learn'&&state.helpReturn){$('#lesson-'+state.lessonOpen).scrollIntoView({block:'start'});$('#lesson-'+state.lessonOpen+' summary').focus({preventScroll:true});}});
window.addEventListener('beforeunload',e=>{if(state.draft.trim()||state.reflection.trim()){e.preventDefault();e.returnValue='';}});
const live=document.createElement('div');live.id='announcement';live.setAttribute('role','status');live.setAttribute('aria-live','polite');live.className='visually-hidden';document.body.append(live);
applyRoute();render();
